4	import { motion, useScroll, useTransform, type Transition } from "framer-motion";
5	
6	interface ParallaxWrapperProps {
7	  children: ReactNode;
8	  yOffset?: number;
9	  scale?: [number, number];
10	  opacity?: [number, number];
11	  rotate?: [number, number];
12	  className?: string;
13	  transition?: Transition;
14	}
15	
16	export default function ParallaxWrapper({
17	  children,
18	  yOffset = 80,
19	  scale,
20	  opacity,
21	  rotate,
22	  className = "",
23	  transition = { duration: 0.8, ease: [0.16, 1, 0.3, 1] },
24	}: ParallaxWrapperProps) {
25	  const ref = useRef<HTMLDivElement>(null);
26	  const { scrollYProgress } = useScroll({
27	    target: ref,
28	    offset: ["start end", "end start"],
29	  });
30	
31	  const y = useTransform(scrollYProgress, [0, 1], [yOffset, -yOffset]);
32	  const s = scale ? useTransform(scrollYProgress, [0, 0.5, 1], [scale[0], 1, scale[1]]) : undefined;
33	  const o = opacity ? useTransform(scrollYProgress, [0, 0.25, 0.75, 1], [opacity[0], 1, 1, opacity[1]]) : undefined;
34	  const r = rotate ? useTransform(scrollYProgress, [0, 1], [rotate[0], rotate[1]]) : undefined;
35	
36	  return (
37	    <motion.div
38	      ref={ref}
39	      style={{ y, scale: s, opacity: o, rotate: r }}
40	      className={className}
41	      transition={transition}
42	    >
43	      {children}
44	    </motion.div>
45	  );
46	}
