@import "tailwindcss";

:root {
  --background: #03040b;
  --foreground: #f9fafb;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);

  --color-azure: #00a2ff;
  --color-azure-glow: #00d2ff;
  --color-databricks: #ff3600;
  --color-databricks-glow: #ff7f50;
  --color-gcp-blue: #4285f4;
  --color-gcp-red: #ea4335;
  --color-gcp-yellow: #fbbc05;
  --color-gcp-green: #34a853;
  --color-deep-bg: #03040b;

  --font-sans: "Outfit", var(--font-outfit), "Inter", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  --font-mono: var(--font-geist-mono), "SF Mono", "Monaco", "Inconsolata", "Fira Code", monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

html, body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans);
  font-feature-settings: "rlig" 1, "calt" 1;
  width: 100%;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* Selection */
::selection {
  background: rgba(0, 162, 255, 0.3);
  color: #fff;
}

/* Custom sleek scrollbar */
::-webkit-scrollbar {
  width: 6px;
}
::-webkit-scrollbar-track {
  background: #03040b;
}
::-webkit-scrollbar-thumb {
  background: #1f2937;
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: #3b82f6;
}

/* --------------------------------------------------------------------------
   Glass system: the UI emerges from the 3D particle space.
   A translucent blur surface plus an inner smoky tint guarantees that
   background neon elements blur out softly while typography stays 100% sharp.
   -------------------------------------------------------------------------- */

.glass {
  background: rgba(3, 4, 11, 0.45);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  border: 1px solid rgba(255, 255, 255, 0.06);
  box-shadow: inset 0 1px 0 0 rgba(255, 255, 255, 0.05),
              0 16px 48px rgba(0, 0, 0, 0.4);
}

/* Card shell: ultra-thin border, high blur, deep inner tint */
.glass-card {
  position: relative;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 1.75rem;
  background: rgba(255, 255, 255, 0.04);
  backdrop-filter: blur(28px);
  -webkit-backdrop-filter: blur(28px);
  box-shadow: inset 0 1px 0 0 rgba(255, 255, 255, 0.04),
              0 24px 70px rgba(0, 0, 0, 0.45);
  transform-style: preserve-3d;
  transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1),
              box-shadow 0.35s cubic-bezier(0.16, 1, 0.3, 1),
              border-color 0.35s ease;
  overflow: hidden;
}

/* Inner protective smoky layer – sits behind card content, above the blur */
.glass-card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(145deg, rgba(3, 4, 11, 0.55), rgba(3, 4, 11, 0.35));
  pointer-events: none;
  z-index: 0;
}

.glass-card:hover {
  border-color: rgba(255, 255, 255, 0.16);
  box-shadow: inset 0 1px 0 0 rgba(255, 255, 255, 0.06),
              0 28px 90px rgba(0, 0, 0, 0.55);
}

/* Inner content wrapper – always above the protective layer */
.card-content {
  position: relative;
  z-index: 1;
}

/* Edge glow hover accent */
.card-glow {
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
  z-index: 0;
}
.card-glow::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(135deg, var(--accent, rgba(255,255,255,0.18)), transparent 55%);
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
}

.glass-card:hover .card-glow {
  opacity: 1;
}

/* Noise overlay */
.noise-overlay {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  pointer-events: none;
  z-index: 9999;
  opacity: 0.035;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E");
}

/* Gradient text utilities */
.gradient-text {
  background: linear-gradient(135deg, #fff 0%, #94a3b8 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.gradient-text-azure {
  background: linear-gradient(135deg, #00d2ff 0%, #0078ff 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.gradient-text-databricks {
  background: linear-gradient(135deg, #ff7f50 0%, #ff3600 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.gradient-text-gcp {
  background: linear-gradient(135deg, #4285f4 0%, #34a853 50%, #fbbc05 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Glowing text utilities */
.glow-azure {
  text-shadow: 0 0 8px rgba(0, 162, 255, 0.4), 0 0 20px rgba(0, 162, 255, 0.15);
}

.glow-databricks {
  text-shadow: 0 0 8px rgba(255, 54, 0, 0.4), 0 0 20px rgba(255, 54, 0, 0.15);
}

.glow-gcp {
  text-shadow: 0 0 8px rgba(66, 133, 244, 0.4), 0 0 20px rgba(66, 133, 244, 0.15);
}

.glow-white {
  text-shadow: 0 0 8px rgba(255, 255, 255, 0.3), 0 0 24px rgba(255, 255, 255, 0.1);
}

/* Glow backgrounds */
.glow-bg-azure {
  box-shadow: 0 0 40px rgba(0, 162, 255, 0.25), 0 0 80px rgba(0, 162, 255, 0.1);
}

.glow-bg-databricks {
  box-shadow: 0 0 40px rgba(255, 54, 0, 0.25), 0 0 80px rgba(255, 54, 0, 0.1);
}

/* Section spacing */
.section {
  position: relative;
  width: 100%;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 6rem 1.5rem;
}

@media (min-width: 768px) {
  .section {
    padding: 8rem 3rem;
  }
}

/* Label / eyebrow */
.eyebrow {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.4);
}

/* Keyframes */
@keyframes float {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-12px); }
}

@keyframes pulse-glow {
  0%, 100% { opacity: 0.5; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.05); }
}

@keyframes spin-slow {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes gradient-shift {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

@keyframes reveal-z {
  from { opacity: 0; transform: perspective(1200px) translateZ(-60px) scale(0.92); filter: blur(8px); }
  to { opacity: 1; transform: perspective(1200px) translateZ(0px) scale(1); filter: blur(0px); }
}

@keyframes draw-line {
  to { stroke-dashoffset: 0; }
}

.animate-float {
  animation: float 6s ease-in-out infinite;
}

.animate-pulse-glow {
  animation: pulse-glow 3s ease-in-out infinite;
}

.animate-spin-slow {
  animation: spin-slow 20s linear infinite;
}

.animate-gradient {
  background-size: 200% 200%;
  animation: gradient-shift 6s ease infinite;
}

/* Premium button: fine-bordered hover glow, no solid block */
.btn-glow {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.625rem;
  padding: 1rem 2.25rem;
  border-radius: 9999px;
  font-weight: 600;
  letter-spacing: 0.025em;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(255, 255, 255, 0.03);
  color: #fff;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1),
              border-color 0.35s ease,
              background 0.35s ease,
              box-shadow 0.35s ease;
  overflow: hidden;
}

.btn-glow::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(500px circle at var(--mouse-x, 50%) var(--mouse-y, 50%), rgba(255, 255, 255, 0.1), transparent 40%);
  opacity: 0;
  transition: opacity 0.35s ease;
  pointer-events: none;
}

.btn-glow:hover {
  border-color: rgba(255, 255, 255, 0.45);
  background: rgba(255, 255, 255, 0.07);
  box-shadow: 0 0 28px rgba(255, 255, 255, 0.12), inset 0 0 20px rgba(255, 255, 255, 0.04);
  transform: translateY(-1px);
}

.btn-glow:hover::before {
  opacity: 1;
}

.btn-glow-primary {
  border-color: rgba(0, 210, 255, 0.35);
  background: rgba(0, 210, 255, 0.05);
}

.btn-glow-primary:hover {
  border-color: rgba(0, 210, 255, 0.75);
  background: rgba(0, 210, 255, 0.11);
  box-shadow: 0 0 32px rgba(0, 210, 255, 0.18), inset 0 0 24px rgba(0, 210, 255, 0.06);
}

.btn-glow-ghost {
  border-color: rgba(255, 255, 255, 0.08);
  background: transparent;
}

.btn-glow-ghost:hover {
  border-color: rgba(255, 255, 255, 0.25);
  background: rgba(255, 255, 255, 0.04);
}

/* Magnetic button base */
.magnetic-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.magnetic-btn::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at var(--mouse-x, 50%) var(--mouse-y, 50%), rgba(255,255,255,0.2), transparent 50%);
  opacity: 0;
  transition: opacity 0.3s ease;
}

.magnetic-btn:hover::before {
  opacity: 1;
}

/* Scroll progress */
.scroll-progress {
  position: fixed;
  top: 0;
  left: 0;
  height: 2px;
  background: linear-gradient(90deg, #00d2ff, #0078ff, #a78bfa);
  z-index: 10000;
  transform-origin: left;
}

/* Cursor spotlight */
.cursor-spotlight {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  opacity: 0.4;
  background: radial-gradient(600px circle at var(--cursor-x, 50%) var(--cursor-y, 50%), rgba(0, 162, 255, 0.06), transparent 40%);
}

/* Hide on mobile */
@media (max-width: 768px) {
  .hide-mobile {
    display: none !important;
  }
}

