  -moz-osx-font-smoothing: grayscale;
}

/* Selection */
::selection {
  background: rgba(0, 162, 255, 0.3);
  color: #fff;
}

/* Custom sleek scrollbar */
::-webkit-scrollbar {
  width: 6px;
}
::-webkit-scrollbar-track {
  background: #03040b;
}
::-webkit-scrollbar-thumb {
  background: #1f2937;
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: #3b82f6;
}

/* --------------------------------------------------------------------------
   Glass system: the UI emerges from the 3D particle space.
   A translucent blur surface plus an inner smoky tint guarantees that
   background neon elements blur out softly while typography stays 100% sharp.
   -------------------------------------------------------------------------- */

.glass {
  background: rgba(3, 4, 11, 0.45);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  border: 1px solid rgba(255, 255, 255, 0.06);
  box-shadow: inset 0 1px 0 0 rgba(255, 255, 255, 0.05),
              0 16px 48px rgba(0, 0, 0, 0.4);
}

/* Card shell: ultra-thin border, high blur, deep inner tint */
.glass-card {
  position: relative;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 1.75rem;
  background: rgba(255, 255, 255, 0.04);
  backdrop-filter: blur(28px);
  -webkit-backdrop-filter: blur(28px);
  box-shadow: inset 0 1px 0 0 rgba(255, 255, 255, 0.04),
              0 24px 70px rgba(0, 0, 0, 0.45);
  transform-style: preserve-3d;
  transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1),
              box-shadow 0.35s cubic-bezier(0.16, 1, 0.3, 1),
              border-color 0.35s ease;
  overflow: hidden;
}

/* Inner protective smoky layer – sits behind card content, above the blur */
.glass-card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(145deg, rgba(3, 4, 11, 0.55), rgba(3, 4, 11, 0.35));
  pointer-events: none;
  z-index: 0;
}

.glass-card:hover {
  border-color: rgba(255, 255, 255, 0.16);
  box-shadow: inset 0 1px 0 0 rgba(255, 255, 255, 0.06),
              0 28px 90px rgba(0, 0, 0, 0.55);
}

/* Inner content wrapper – always above the protective layer */
.card-content {
  position: relative;
  z-index: 1;
}

/* Edge glow hover accent */
.card-glow {
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
  z-index: 0;
}
.card-glow::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(135deg, var(--accent, rgba(255,255,255,0.18)), transparent 55%);
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
}

.glass-card:hover .card-glow {
  opacity: 1;
}

/* Noise overlay */
.noise-overlay {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  pointer-events: none;
  z-index: 9999;
  opacity: 0.035;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E");
}

