5	interface AnimatedTextProps {
6	  text: string;
7	  className?: string;
8	  as?: "h1" | "h2" | "h3" | "p" | "span";
9	  type?: "chars" | "words";
10	  delay?: number;
11	  stagger?: number;
12	  duration?: number;
13	  once?: boolean;
14	}
15	
16	export default function AnimatedText({
17	  text,
18	  className = "",
19	  as: Tag = "span",
20	  type = "words",
21	  delay = 0,
22	  stagger: staggerDelay = 0.04,
23	  duration = 0.7,
24	  once = true,
25	}: AnimatedTextProps) {
26	  const items = type === "chars" ? text.split("") : text.split(" ");
27	
28	  const container = {
29	    hidden: {},
30	    visible: {
31	      transition: {
32	        staggerChildren: staggerDelay,
33	        delayChildren: delay,
34	      },
35	    },
36	  };
37	
38	  const child = {
39	    hidden: {
40	      opacity: 0,
41	      scale: 0.85,
42	      filter: "blur(10px)",
43	    },
44	    visible: {
45	      opacity: 1,
