49	        duration,
50	        ease: [0.16, 1, 0.3, 1],
51	      },
52	    },
53	  };
54	
55	  return (
56	    <motion.span
57	      className={`inline-block ${className}`}
58	      initial="hidden"
59	      whileInView="visible"
60	      viewport={{ once }}
61	      variants={container}
62	    >
63	      <Tag className="inline">
64	        {items.map((item, i) => (
65	          <motion.span
