import { chromium } from 'playwright';

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  // extra wait for images
  await page.waitForTimeout(1000);
  await page.screenshot({ path: '/tmp/v4-full.png', fullPage: true });
  // about section crop
  await page.evaluate(() => window.scrollTo(0, 900));
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/v4-about.png', clip: { x: 0, y: 0, width: 1440, height: 900 } });
  // experience
  await page.evaluate(() => window.scrollTo(0, 2300));
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/v4-exp.png', clip: { x: 0, y: 0, width: 1440, height: 900 } });
  // skills
  await page.evaluate(() => window.scrollTo(0, 3700));
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/v4-skills.png', clip: { x: 0, y: 0, width: 1440, height: 900 } });
  await browser.close();
  console.log('done');
})();

